// Valida o envio do site (/api/simulador). Segunda barreira: o site já valida e sanitiza o SVG.
const H = (typeof helpers !== 'undefined') ? helpers : this.helpers;
const item = $input.first();
const j = item.json, b = j.body || {}, bin = item.binary || {};
const s = (v, n = 200) => String(v ?? '').replace(/[\u0000-\u001f]/g, ' ').trim().slice(0, n);
const lead = {
  recebido_em: new Date().toISOString(),
  etapa: s(b.etapa, 20), nome: s(b.nome, 120), email: s(b.email, 160).toLowerCase(), empresa: s(b.empresa, 160),
  whatsapp: s(b.whatsapp, 40), produto: s(b.produto, 80), produto_nome: s(b.produto_nome, 120), cor: s(b.cor, 60),
  cor_hex: s(b.cor_hex, 9), tecnica: s(b.tecnica, 160), material: s(b.material, 160), aplicacao: s(b.aplicacao, 10),
  tamanho: s(b.tamanho, 4), pagina: s(b.pagina, 200), consentimento: s(b.consentimento, 5),
  ip: s((j.headers || {})['x-real-ip'], 60), logo_arquivo: '', logo_tipo: '', logo_bytes: 0,
};
const cfg = {
  remetente: s(j.cfg_remetente, 200), email_equipe: s(j.cfg_email_equipe, 200), site: s(j.cfg_site, 200).replace(/\/$/, ''),
  whatsapp: s(j.cfg_whatsapp, 20).replace(/\D/g, ''), ia_ativa: j.cfg_ia_ativa === true || j.cfg_ia_ativa === 'true',
  ia_enviar_ao_cliente: j.cfg_ia_enviar_ao_cliente === true || j.cfg_ia_enviar_ao_cliente === 'true',
  ia_modelo: s(j.cfg_ia_modelo, 60), ia_qualidade: s(j.cfg_ia_qualidade, 10),
};
const bot = s(b['bot-field']) !== '';
let motivo = '';
if (!['mockup', 'lembrete'].includes(lead.etapa)) motivo = 'etapa';
else if (lead.consentimento !== 'sim') motivo = 'consentimento';
else if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(lead.email)) motivo = 'email';
const binary = {};
if (!motivo && lead.etapa === 'mockup') {
  const lg = bin.logo, mk = bin.mockup;
  if (lead.nome.length < 2) motivo = 'nome';
  else if (!/^[a-z0-9-]{3,60}$/.test(lead.produto)) motivo = 'produto';
  else if (!lg || !mk) motivo = 'arquivos';
  else if (!['image/png', 'image/jpeg', 'image/svg+xml'].includes(lg.mimeType) || Number(lg.bytes || 0) > 5 * 1024 * 1024) motivo = 'logo';
  else if (!['image/jpeg', 'image/png', 'image/webp'].includes(mk.mimeType) || Number(mk.bytes || 0) > 4 * 1024 * 1024) motivo = 'mockup';
  else {
    const lb = await H.getBinaryDataBuffer(0, 'logo');
    if (lg.mimeType === 'image/svg+xml') {
      const t = lb.toString('utf8');
      if (!/<svg[\s>]/i.test(t) || /<script|<foreignObject|<iframe|<!ENTITY|\son[a-z]+\s*=|javascript:|href\s*=\s*["'](?!#|data:image\/)/i.test(t)) motivo = 'logo';
    } else if (!((lb[0] === 0x89 && lb[1] === 0x50 && lb[2] === 0x4E) || (lb[0] === 0xFF && lb[1] === 0xD8))) motivo = 'logo';
    const mb = await H.getBinaryDataBuffer(0, 'mockup');
    if (!((mb[0] === 0xFF && mb[1] === 0xD8) || (mb[0] === 0x89 && mb[1] === 0x50) || mb.subarray(8, 12).toString() === 'WEBP')) motivo = motivo || 'mockup';
    if (!motivo) {
      const ext = { 'image/png': 'png', 'image/jpeg': 'jpg', 'image/svg+xml': 'svg' }[lg.mimeType];
      const slug = x => x.normalize('NFKD').replace(/[^\w-]+/g, '-').replace(/^-+|-+$/g, '').toLowerCase().slice(0, 40) || 'x';
      lead.logo_arquivo = s(lg.fileName, 120); lead.logo_tipo = lg.mimeType; lead.logo_bytes = Number(lg.bytes || lb.length);
      binary.logo = { ...lg, fileName: `logo-${slug(lead.empresa || lead.nome)}.${ext}` };
      binary.mockup = { ...mk, fileName: `mockup-${lead.produto}-${slug(lead.cor)}.jpg` };
    }
  }
}
const configurado = !!(cfg.remetente && cfg.email_equipe);
if (!bot && !motivo && !configurado) motivo = 'configuracao';
return [{ json: { ...lead, cfg, bot, motivo: bot ? 'bot' : motivo, valido: !bot && !motivo }, binary }];

// Entrada da IA: a composição determinística (mockup) é a base; o prompt pede para não mexer no logo nem no produto.
const v = $('Validar envio').first();
const prompt = [
  'Photorealistic product photograph retouch. Keep everything exactly as it is: the product, its shape, colour, materials,',
  'camera angle, background, framing and lighting direction. The logo already applied on the product must stay identical:',
  'same shapes, letters, colours, proportions, size and position. Only refine how the logo application sits on the material',
  `(${v.json.tecnica || 'brand application'} on ${v.json.material || 'the product'}): realistic texture, subtle relief and natural light interaction.`,
  'Do not add, remove or rewrite any text, logo, object or watermark.',
].join(' ');
return [{ json: { prompt, modelo: v.json.cfg.ia_modelo || 'gpt-image-1.5', qualidade: v.json.cfg.ia_qualidade || 'medium' }, binary: { mockup: v.binary.mockup } }];

// Converte a resposta da OpenAI (base64) em arquivo. Se a IA falhar, o fluxo segue só com o mockup determinístico.
const H = (typeof helpers !== 'undefined') ? helpers : this.helpers;
const r = $input.first().json || {};
const b64 = r.data && r.data[0] && r.data[0].b64_json;
if (!b64) return [{ json: { premium: false, ia_erro: String((r.error && (r.error.message || r.error)) || 'sem imagem').slice(0, 300) } }];
const premium = await H.prepareBinaryData(Buffer.from(b64, 'base64'), 'mockup-ilustrativo-ia.jpg', 'image/jpeg');
return [{ json: { premium: true, ia_erro: '' }, binary: { premium } }];

// Monta os dois e-mails do pedido de mockup: ao cliente (mockup em alta) e à equipe TaMa (dados + arquivos).
const v = $('Validar envio').first(), d = v.json, c = d.cfg;
const inp = $input.first();
const temIA = !!(inp.json && inp.json.premium && inp.binary && inp.binary.premium);
const e = x => String(x ?? '').replace(/[&<>"']/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));
const wa = c.whatsapp ? `https://wa.me/${c.whatsapp}` : '';
const iaCliente = temIA && c.ia_enviar_ao_cliente;
const p = t => `<p style="margin:0 0 14px;font:15px/1.6 Arial,sans-serif;color:#282322">${t}</p>`;
const htmlCliente = `<div style="max-width:560px">` +
  p(`Olá, ${e(d.nome.split(' ')[0])}!`) +
  p(`Em anexo está o mockup em alta resolução de <strong>${e(d.produto_nome)}</strong> na cor <strong>${e(d.cor)}</strong>, com a sua marca aplicada.`) +
  p(`É um mockup ilustrativo: cores, técnica de personalização, tamanho e posição da marca são definidos e aprovados na proposta, antes da produção.`) +
  (iaCliente ? p(`Também enviamos uma versão com acabamento ilustrativo gerado por IA. Ela pode alterar detalhes do logo ou do produto; a referência é o mockup principal.`) : '') +
  p(`Quer levar a ideia adiante? Responda este e-mail ou <a href="${c.site}/solicitar-proposta/" style="color:#501B2B">peça uma proposta</a>${wa ? ` ou fale no <a href="${wa}" style="color:#501B2B">WhatsApp</a>` : ''}.`) +
  p(`Equipe TaMa Creative<br><a href="${c.site}" style="color:#501B2B">${e(c.site.replace(/^https?:\/\//, ''))}</a>`) +
  `<p style="margin:24px 0 0;font:12px/1.5 Arial,sans-serif;color:#6B625D">Você recebeu este e-mail porque pediu um mockup em ${e(c.site.replace(/^https?:\/\//, ''))}/veja-sua-marca/. O seu logo é usado só para este mockup e para a proposta, se você pedir, e é apagado em até 30 dias. <a href="${c.site}/privacidade/#simulador" style="color:#6B625D">Privacidade</a>.</p></div>`;
const textoCliente = `Olá, ${d.nome.split(' ')[0]}!\n\nEm anexo está o mockup em alta resolução de ${d.produto_nome} na cor ${d.cor}, com a sua marca aplicada.\n\nÉ um mockup ilustrativo: cores, técnica de personalização, tamanho e posição da marca são definidos e aprovados na proposta, antes da produção.\n${iaCliente ? '\nTambém enviamos uma versão com acabamento ilustrativo gerado por IA. Ela pode alterar detalhes do logo ou do produto; a referência é o mockup principal.\n' : ''}\nQuer levar a ideia adiante? Responda este e-mail ou peça uma proposta: ${c.site}/solicitar-proposta/${wa ? `\nWhatsApp: ${wa}` : ''}\n\nEquipe TaMa Creative\n\nVocê recebeu este e-mail porque pediu um mockup em ${c.site}/veja-sua-marca/. O seu logo é usado só para este mockup e para a proposta, se você pedir, e é apagado em até 30 dias. Privacidade: ${c.site}/privacidade/#simulador`;
const linhas = [['Nome', d.nome], ['E-mail', d.email], ['Empresa', d.empresa], ['WhatsApp', d.whatsapp], ['Peça', `${d.produto_nome} (${d.produto})`],
  ['Cor', d.cor], ['Técnica de referência', d.tecnica], ['Aplicação do logo', d.aplicacao === 'cores' ? 'cores do logo' : 'um tom'], ['Tamanho', d.tamanho ? d.tamanho + '%' : ''],
  ['Página', d.pagina], ['Logo enviado', `${d.logo_arquivo} (${d.logo_tipo}, ${Math.round(d.logo_bytes / 1024)} KB)`],
  ['Render IA', c.ia_ativa ? (temIA ? (iaCliente ? 'gerado e enviado ao cliente' : 'gerado, só para a equipe revisar') : 'falhou: ' + (inp.json.ia_erro || '')) : 'desligado'],
  ['Recebido em', d.recebido_em]];
const htmlEquipe = `<div style="font:14px/1.5 Arial,sans-serif;color:#282322"><p><strong>Novo lead do simulador "Veja sua marca".</strong> O mockup e o logo estão em anexo.</p><table cellpadding="6" style="border-collapse:collapse">` +
  linhas.filter(l => l[1]).map(l => `<tr><td style="color:#6B625D;border-bottom:1px solid #E6DDD3">${e(l[0])}</td><td style="border-bottom:1px solid #E6DDD3">${e(l[1])}</td></tr>`).join('') +
  `</table><p style="color:#6B625D;font-size:12px">LGPD: apague este e-mail e os anexos em até 30 dias, salvo se o cliente contratar o projeto (política em ${e(c.site)}/privacidade/#simulador).</p></div>`;
const textoEquipe = 'Novo lead do simulador "Veja sua marca". O mockup e o logo estão em anexo.\n\n' + linhas.filter(l => l[1]).map(l => `${l[0]}: ${l[1]}`).join('\n') +
  '\n\nLGPD: apague este e-mail e os anexos em até 30 dias, salvo se o cliente contratar o projeto.';
const binary = { mockup: v.binary.mockup, logo: v.binary.logo };
if (temIA) binary.premium = inp.binary.premium;
return [{ json: {
  remetente: c.remetente, equipe: c.email_equipe, cliente: d.email,
  assunto_cliente: `Seu mockup TaMa: ${d.produto_nome} com a sua marca`,
  assunto_equipe: `Simulador: ${d.nome}${d.empresa ? ' (' + d.empresa + ')' : ''} · ${d.produto_nome}, ${d.cor}`,
  html_cliente: htmlCliente, texto_cliente: textoCliente, html_equipe: htmlEquipe, texto_equipe: textoEquipe,
  anexos_cliente: iaCliente ? 'mockup,premium' : 'mockup', anexos_equipe: temIA ? 'mockup,logo,premium' : 'mockup,logo',
}, binary }];

// Pedido do convite de saída: só o e-mail. Envia o link do simulador e avisa a equipe.
const d = $('Validar envio').first().json, c = d.cfg;
const url = `${c.site}/veja-sua-marca/`;
const p = t => `<p style="margin:0 0 14px;font:15px/1.6 Arial,sans-serif;color:#282322">${t}</p>`;
return [{ json: {
  remetente: c.remetente, equipe: c.email_equipe, cliente: d.email,
  assunto_cliente: 'Seu link para ver a sua marca nos produtos TaMa',
  html_cliente: `<div style="max-width:560px">` + p('Olá!') + p(`Como combinado, aqui está o link do simulador: envie o logo, escolha a peça e a cor, e veja a prévia na hora.`) +
    p(`<a href="${url}" style="display:inline-block;padding:12px 22px;border-radius:999px;background:#501B2B;color:#fff;text-decoration:none;font-weight:bold">Ver com a minha marca</a>`) +
    p(`Equipe TaMa Creative`) + `<p style="margin:24px 0 0;font:12px/1.5 Arial,sans-serif;color:#6B625D">Você recebeu este e-mail porque pediu o link em ${c.site.replace(/^https?:\/\//, '')}. <a href="${c.site}/privacidade/#simulador" style="color:#6B625D">Privacidade</a>.</p></div>`,
  texto_cliente: `Olá!\n\nComo combinado, aqui está o link do simulador: ${url}\nEnvie o logo, escolha a peça e a cor, e veja a prévia na hora.\n\nEquipe TaMa Creative\n\nVocê recebeu este e-mail porque pediu o link em ${c.site}. Privacidade: ${c.site}/privacidade/#simulador`,
  assunto_equipe: `Simulador: pedido de link (${d.email})`,
  html_equipe: `<p style="font:14px/1.5 Arial,sans-serif">Um visitante pediu o link do simulador pelo convite de saída.</p><p style="font:14px/1.5 Arial,sans-serif">E-mail: ${d.email.replace(/[<>&"]/g, '')}<br>Página: ${String(d.pagina).replace(/[<>&"]/g, '')}<br>Recebido em: ${d.recebido_em}</p>`,
  texto_equipe: `Um visitante pediu o link do simulador pelo convite de saída.\nE-mail: ${d.email}\nPágina: ${d.pagina}\nRecebido em: ${d.recebido_em}`,
} }];
